Based on one of the comments on the OpenAI bug report, the following alternative for the [create_gpt_vector_store method on openai_utils.py](https://github.com/microsoft/autogen/blob/enhance-vertexai-integration/autogen/oai/openai_utils.py#L699) works fine in my local tests with `pytest test/agentchat/contrib/test_gpt_assistant.py -k "test_get_assistant_files or test_assistant_retrieval"` (only the failed methods are selected)

```python
def create_gpt_vector_store(client: OpenAI, name: str, file_ids: List[str]) -> Any:
    """Create a openai vector store for gpt assistant"""

    try:
        vector_store = client.beta.vector_stores.create(name=name)
    except Exception as e:
        raise AttributeError(f"Failed to create vector store, please install the latest OpenAI python package: {e}")

    for file_id in file_ids:
        vs_file = client.beta.vector_stores.files.create_and_poll(vector_store_id=vector_store.id, file_id=file_id)
        if vs_file.status == "in_progress":
            time.sleep(1)
            logging.debug(f"File id {vs_file.id} status: {vs_file.status}")
            vs_file = client.beta.vector_stores.files.poll(vector_store_id=vector_store.id, file_id=file_id)

        if vs_file.status != "completed":
            raise ValueError(f"Failed to upload files to vector store {vector_store.id}:{vs_file.status}")

    return vector_store
```

